SELECT

FROM sensor_slave_data
WHERE device_id = #{deviceId}
ORDER BY timestamp DESC
LIMIT #{limit}

SELECT

FROM sensor_slave_data
WHERE device_id = #{deviceId}
AND address = #{address}
ORDER BY timestamp DESC
LIMIT #{limit}

SELECT

FROM sensor_slave_data
WHERE device_id = #{deviceId}
AND timestamp BETWEEN #{startTime} AND #{endTime}
ORDER BY timestamp DESC
